// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceProgressListener {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    static var vtable: UniffiVTableCallbackInterfaceProgressListener = UniffiVTableCallbackInterfaceProgressListener(
        onProgress: { (
            uniffiHandle: UInt64,
            phase: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterTypeProgressListener.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.onProgress(
                     phase: try FfiConverterOptionTypeOrderProgress.lift(phase)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            let result = try? FfiConverterTypeProgressListener.handleMap.remove(handle: uniffiHandle)
            if result == nil {
                print("Uniffi callback interface ProgressListener: handle missing in uniffiFree")
            }
        }
    )
}

private func uniffiCallbackInitProgressListener() {
    uniffi_snackpilot_core_fn_init_callback_vtable_progresslistener(&UniffiCallbackInterfaceProgressListener.vtable)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeProgressListener: FfiConverter {
    fileprivate static var handleMap = UniffiHandleMap<ProgressListener>()

    typealias FfiType = UnsafeMutableRawPointer
    typealias SwiftType = ProgressListener

    public static func lift(_ pointer: UnsafeMutableRawPointer) throws -> ProgressListener {
        return ProgressListenerImpl(unsafeFromRawPointer: pointer)
    }

    public static func lower(_ value: ProgressListener) -> UnsafeMutableRawPointer {
        guard let ptr = UnsafeMutableRawPointer(bitPattern: UInt(truncatingIfNeeded: handleMap.insert(obj: value))) else {
            fatalError("Cast to UnsafeMutableRawPointer failed")
        }
        return ptr
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ProgressListener {
        let v: UInt64 = try readInt(&buf)
        // The Rust code won't compile if a pointer won't fit in a UInt64.
        // We have to go via `UInt` because that's the thing that's the size of a pointer.
        let ptr = UnsafeMutableRawPointer(bitPattern: UInt(truncatingIfNeeded: v))
        if (ptr == nil) {
            throw UniffiInternalError.unexpectedNullPointer
        }
        return try lift(ptr!)
    }

    public static func write(_ value: ProgressListener, into buf: inout [UInt8]) {
        // This fiddling is because `Int` is the thing that's the same size as a pointer.
        // The Rust code won't compile if a pointer won't fit in a `UInt64`.
        writeInt(&buf, UInt64(bitPattern: Int64(Int(bitPattern: lower(value)))))
    }
}




#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeProgressListener_lift(_ pointer: UnsafeMutableRawPointer) throws -> ProgressListener {
    return try FfiConverterTypeProgressListener.lift(pointer)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeProgressListener_lower(_ value: ProgressListener) -> UnsafeMutableRawPointer {
    return FfiConverterTypeProgressListener.lower(value)
}




/**
 * The single exported core object. Holds the two scraping sessions, the three feature
 * stores, and the shared KV + clock.
 */
public protocol SnackPilotCoreProtocol : AnyObject {
    
    func billingError()  -> String?
    
    func billingMonthOptions()  -> [MonthOption]
    
    func cancelOrder(positionId: String) async throws 
    
    /**
     * Batch cancel (multi-select — one edit-mode session for all).
     */
    func cancelOrders(positionIds: [String]) async throws 
    
    func cancelReminderCommand(isAtCompany: Bool)  -> NotificationCommand?
    
    /**
     * `clearCompanyLocation` (§1): drop the saved location and reset the geofence flag.
     */
    func clearCompanyLocation() 
    
    func clearPendingChanges()  -> MenuSnapshot
    
    func companyLocation()  -> CompanyLocation?
    
    func confirmOrders() async throws 
    
    func dailyReminderCommand(settings: DailyReminderSettings)  -> NotificationCommand?
    
    func dailyReminderSettings()  -> DailyReminderSettings
    
    /**
     * Demo menus rendered as a snapshot — no network (demo-mode §5.2). Lets the shell show
     * real menu data offline (store review / FFI preview) without touching the live server.
     */
    func demoMenuSnapshot()  -> MenuSnapshot
    
    func fetchBilling(offset: UInt8, force: Bool) async throws 
    
    /**
     * Fetch the operator broadcast message (from the public gist), or `None` when the gist is
     * empty or unreachable. Best-effort: the shell shows a banner only when this returns a
     * non-empty string. Uses a fresh cookieless session (redirects followed — the gist raw URL
     * 302s to a CDN host).
     */
    func fetchBroadcast() async  -> String?
    
    func fetchMenus(force: Bool) async throws  -> MenuSnapshot
    
    func fetchOrders() async throws  -> [NotificationCommand]
    
    func fetchVentopayBilling(offset: UInt8, force: Bool) async throws 
    
    func geofenceCommands(event: GeofenceEvent)  -> [NotificationCommand]
    
    func gourmetBillingMonth(monthKey: String)  -> GourmetMonthlyBilling?
    
    func gourmetIsAuthenticated()  -> Bool
    
    func gourmetLogin(creds: Credentials) async throws  -> GourmetUserInfo
    
    func gourmetLogout() async throws 
    
    func gourmetUserInfo()  -> GourmetUserInfo?
    
    func isAtCompany()  -> Bool
    
    func isOrderingCutoff(dateKey: String)  -> Bool
    
    func loadCachedBillingMonths() 
    
    func loadCachedMenus() 
    
    func loadCachedOrders() 
    
    func logActivate(hours: UInt32) 
    
    func logClear() 
    
    func logEntries()  -> [LogEntry]
    
    func logIsActive()  -> Bool
    
    func menuSnapshot()  -> MenuSnapshot
    
    /**
     * Current submit-pipeline phase, if a submit is in flight (menus §6.6). Lets the shell
     * render the order-progress banner (Adding/Confirming/Cancelling/Refreshing).
     */
    func orderProgress()  -> OrderProgress?
    
    func orders()  -> [OrderedMenu]
    
    func ordersError()  -> String?
    
    func refreshAvailability() async throws  -> MenuSnapshot
    
    /**
     * Background new-menu check. Uses a FRESH, isolated Gourmet session (own cookie store —
     * deliberate v2 change, notifications-new-menu §3.3).
     */
    func runMenuCheck(creds: Credentials?) async throws  -> MenuCheckResult
    
    /**
     * Headless order-sync job (docs/architecture §4.4; notifications-daily-reminder §2,
     * notifications-location §6): the background task body — loads **cached** orders (no
     * network, v1's "no concurrent scraping" rule) and returns the daily + cancel reminder
     * commands to deliver. Called from BGTaskScheduler / WorkManager with no UI attached.
     */
    func runOrderSyncCheck()  -> [NotificationCommand]
    
    func selectedDate()  -> String?
    
    func setCompanyLocation(latitude: Double, longitude: Double) 
    
    /**
     * The settings toggle persists the time **before** the enabled flag (§9 step 2); callers
     * invoke `set_daily_reminder_time` first, then this.
     */
    func setDailyReminderEnabled(enabled: Bool) 
    
    func setDailyReminderTime(hour: UInt8, minute: UInt8) 
    
    func setIsAtCompany(value: Bool) 
    
    func setSelectedDate(dateKey: String) 
    
    func splitOrders()  -> OrdersSplit
    
    /**
     * Submit pending orders/cancellations (§6.5), then refresh the order store.
     */
    func submitOrders(progress: ProgressListener?) async throws  -> MenuSnapshot
    
    func togglePending(menuId: String, dateKey: String)  -> MenuSnapshot
    
    func ventopayBillingMonth(monthKey: String)  -> VentopayMonthlyBilling?
    
    func ventopayIsAuthenticated()  -> Bool
    
    func ventopayLogin(creds: Credentials) async throws 
    
    func ventopayLogout() async throws 
    
}

