public struct VentopayTransaction {
    public var id: String
    public var dateEpochMs: Int64
    public var amount: Double
    public var restaurant: String
    public var location: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(id: String, dateEpochMs: Int64, amount: Double, restaurant: String, location: String) {
        self.id = id
        self.dateEpochMs = dateEpochMs
        self.amount = amount
        self.restaurant = restaurant
        self.location = location
    }
}



extension VentopayTransaction: Equatable, Hashable {
    public static func ==(lhs: VentopayTransaction, rhs: VentopayTransaction) -> Bool {
        if lhs.id != rhs.id {
            return false
        }
        if lhs.dateEpochMs != rhs.dateEpochMs {
            return false
        }
        if lhs.amount != rhs.amount {
            return false
        }
        if lhs.restaurant != rhs.restaurant {
            return false
        }
        if lhs.location != rhs.location {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(id)
        hasher.combine(dateEpochMs)
        hasher.combine(amount)
        hasher.combine(restaurant)
        hasher.combine(location)
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeVentopayTransaction: FfiConverterRustBuffer {
    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> VentopayTransaction {
        return
            try VentopayTransaction(
                id: FfiConverterString.read(from: &buf), 
                dateEpochMs: FfiConverterInt64.read(from: &buf), 
                amount: FfiConverterDouble.read(from: &buf), 
                restaurant: FfiConverterString.read(from: &buf), 
                location: FfiConverterString.read(from: &buf)
        )
    }

    public static func write(_ value: VentopayTransaction, into buf: inout [UInt8]) {
        FfiConverterString.write(value.id, into: &buf)
        FfiConverterInt64.write(value.dateEpochMs, into: &buf)
        FfiConverterDouble.write(value.amount, into: &buf)
        FfiConverterString.write(value.restaurant, into: &buf)
        FfiConverterString.write(value.location, into: &buf)
    }
}


