public enum CoreError {

    
    
    /**
     * LoginFailed carries the full message verbatim (Gourmet or Ventopay variant text).
     */
    case LoginFailed(detail: String
    )
    case SessionExpired
    case NotLoggedIn
    case AddToCartFailed(detail: String
    )
    case EditModeFailed
    /**
     * Parser errors, incl. missing-token messages, carried verbatim.
     */
    case Parse(detail: String
    )
    /**
     * Transport-level failure or HTTP status >= 400. `status` is Some(status) for a real
     * HTTP status response, None for transport-level failures (DNS, timeout, …).
     */
    case Http(detail: String, status: UInt16?
    )
    case Storage(detail: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCoreError: FfiConverterRustBuffer {
    typealias SwiftType = CoreError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .LoginFailed(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 2: return .SessionExpired
        case 3: return .NotLoggedIn
        case 4: return .AddToCartFailed(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 5: return .EditModeFailed
        case 6: return .Parse(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 7: return .Http(
            detail: try FfiConverterString.read(from: &buf), 
            status: try FfiConverterOptionUInt16.read(from: &buf)
            )
        case 8: return .Storage(
            detail: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CoreError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .LoginFailed(detail):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(detail, into: &buf)
            
        
        case .SessionExpired:
            writeInt(&buf, Int32(2))
        
        
        case .NotLoggedIn:
            writeInt(&buf, Int32(3))
        
        
        case let .AddToCartFailed(detail):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(detail, into: &buf)
            
        
        case .EditModeFailed:
            writeInt(&buf, Int32(5))
        
        
        case let .Parse(detail):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Http(detail,status):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(detail, into: &buf)
            FfiConverterOptionUInt16.write(status, into: &buf)
            
        
        case let .Storage(detail):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(detail, into: &buf)
            
        }
    }
}


extension CoreError: Equatable, Hashable {}

extension CoreError: Foundation.LocalizedError {
    public var errorDescription: String? {
        String(reflecting: self)
    }
}

