/**
 * The delivery contract between core decisions and the shell's OS notification APIs
 * (docs/architecture §4.2). The shell executes these 1:1; re-issuing an id replaces the
 * pending notification with that id.
 */

public enum NotificationCommand {
    
    /**
     * Schedule a local notification to fire at `fire_at_epoch_ms`. `channel_id` is `None`
     * when v1 attaches no Android channel (falls back to the OS default).
     */
    case scheduleAt(id: String, title: String, body: String, channelId: String?, fireAtEpochMs: Int64, screen: String?
    )
    /**
     * Deliver now. `channel_id` is `None` for v1's immediate-fire paths (no channel).
     */
    case fireNow(id: String, title: String, body: String, channelId: String?, screen: String?
    )
    /**
     * Cancel any pending notification with `id`.
     */
    case cancelPending(id: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeNotificationCommand: FfiConverterRustBuffer {
    typealias SwiftType = NotificationCommand

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> NotificationCommand {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .scheduleAt(id: try FfiConverterString.read(from: &buf), title: try FfiConverterString.read(from: &buf), body: try FfiConverterString.read(from: &buf), channelId: try FfiConverterOptionString.read(from: &buf), fireAtEpochMs: try FfiConverterInt64.read(from: &buf), screen: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 2: return .fireNow(id: try FfiConverterString.read(from: &buf), title: try FfiConverterString.read(from: &buf), body: try FfiConverterString.read(from: &buf), channelId: try FfiConverterOptionString.read(from: &buf), screen: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 3: return .cancelPending(id: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: NotificationCommand, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .scheduleAt(id,title,body,channelId,fireAtEpochMs,screen):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(id, into: &buf)
            FfiConverterString.write(title, into: &buf)
            FfiConverterString.write(body, into: &buf)
            FfiConverterOptionString.write(channelId, into: &buf)
            FfiConverterInt64.write(fireAtEpochMs, into: &buf)
            FfiConverterOptionString.write(screen, into: &buf)
            
        
        case let .fireNow(id,title,body,channelId,screen):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(id, into: &buf)
            FfiConverterString.write(title, into: &buf)
            FfiConverterString.write(body, into: &buf)
            FfiConverterOptionString.write(channelId, into: &buf)
            FfiConverterOptionString.write(screen, into: &buf)
            
        
        case let .cancelPending(id):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(id, into: &buf)
            
        }
    }
}


